package co.edu.umb.boleteria.service;
import co.edu.umb.boleteria.domain.*;import co.edu.umb.boleteria.event.AforoCambiadoEvent;import co.edu.umb.boleteria.repository.*;import co.edu.umb.boleteria.web.dto.ReservaDto;import co.edu.umb.boleteria.web.excepciones.*;import jakarta.persistence.EntityManager;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.ApplicationEventPublisher;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class ReservaService {
 final LocalidadRepository localidades;final ReservaRepository reservas;final AuditoriaRepository auditorias;final ApplicationEventPublisher eventos;final EntityManager em;final int ttl;
 public ReservaService(LocalidadRepository l,ReservaRepository r,AuditoriaRepository a,ApplicationEventPublisher e,EntityManager em,@Value("${app.reservas.ttl-minutos:10}") int ttl){localidades=l;reservas=r;auditorias=a;eventos=e;this.em=em;this.ttl=ttl;}
 @Transactional public ReservaDto crearReserva(UUID id,String usuario,int cantidad){Localidad l=localidades.findByIdWithPessimisticLock(id).orElseThrow(NoEncontradaException::new);long t0=System.nanoTime();if(!l.validarDisponibilidad(cantidad))throw new SinDisponibilidadException();l.reservar(cantidad);Instant ahora=Instant.now();Reserva r=reservas.save(new Reserva(l,usuario,cantidad,ahora,ahora.plusSeconds(ttl*60L)));String nodo=(String)em.createNativeQuery("select current_setting('cluster_name')").getSingleResult();auditorias.save(new AuditoriaTransaccion(r,nodo,(int)((System.nanoTime()-t0)/1_000_000)));eventos.publishEvent(new AforoCambiadoEvent(l.getId(),l.getEstado(),l.getCuposDisponibles()));return ReservaDto.of(r,nodo);}
 @Transactional public Reserva confirmar(UUID id){Reserva r=obtenerConLocalidad(id);if(r.getEstado()!=EstadoReserva.ACTIVA||!r.getFechaExpiracion().isAfter(Instant.now()))throw new SinDisponibilidadException();r.setEstado(EstadoReserva.CONFIRMADA);return r;}
 @Transactional public void cancelar(UUID id){Reserva r=obtenerConLocalidad(id);if(r.getEstado()!=EstadoReserva.ACTIVA)throw new SinDisponibilidadException();r.getLocalidad().liberar(r.getCantidad());r.setEstado(EstadoReserva.CANCELADA);emitir(r.getLocalidad());}
 @Transactional public int expirarVencidas(){int n=0;for(Reserva pendiente:reservas.vencidas(Instant.now())){Localidad l=localidades.findByIdWithPessimisticLock(pendiente.getLocalidad().getId()).orElseThrow();Reserva r=reservas.findLocked(pendiente.getId()).orElseThrow();if(r.getEstado()==EstadoReserva.ACTIVA&& !r.getFechaExpiracion().isAfter(Instant.now())){l.liberar(r.getCantidad());r.setEstado(EstadoReserva.EXPIRADA);emitir(l);n++;}}return n;}
 private Reserva obtenerConLocalidad(UUID id){Reserva preliminar=reservas.findById(id).orElseThrow(NoEncontradaException::new);localidades.findByIdWithPessimisticLock(preliminar.getLocalidad().getId()).orElseThrow(NoEncontradaException::new);return reservas.findLocked(id).orElseThrow(NoEncontradaException::new);}
 private void emitir(Localidad l){eventos.publishEvent(new AforoCambiadoEvent(l.getId(),l.getEstado(),l.getCuposDisponibles()));}
}
